  -- H.R. 8034 (118th)
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_118_h_r_8034, 'israel_support', 100, true, 'yea_supports',
      'FY2024 emergency supplemental of roughly $26.4 billion for the situation in Israel: Israeli cooperative missile-defense programs including Iron Dome and David''s Sling, Iron Beam procurement, Foreign Military Financing for Israel, replacement of U.S. defense articles and services provided to Israel, U.S. Central Command operations, and humanitarian assistance for Gaza. Enacted as Division A of P.L. 118-50. The 58 nays are members who declined to fund Israel''s defense on a bill that asked nothing else of them, which makes this the most direct enacted test of the issue in the window. A yea funds it.',
