-- ---------------------------------------------------------------------------
-- Verification. Read-only, scoped to exactly this pass's roll calls by tuple, so it can
-- only ever fail on data this migration is responsible for.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 117::integer, 1::integer, 275::integer),
    ('house'::text, 118::integer, 1::integer, 491::integer),
    ('house'::text, 118::integer, 1::integer, 577::integer),
    ('house'::text, 118::integer, 2::integer, 38::integer),
    ('house'::text, 118::integer, 2::integer, 152::integer),
    ('house'::text, 118::integer, 2::integer, 217::integer),
    ('senate'::text, 118::integer, 2::integer, 292::integer),
    ('senate'::text, 118::integer, 2::integer, 293::integer),
    ('senate'::text, 118::integer, 2::integer, 294::integer),
    ('senate'::text, 119::integer, 1::integer, 165::integer),
    ('senate'::text, 119::integer, 1::integer, 166::integer),
    ('senate'::text, 119::integer, 1::integer, 454::integer),
    ('senate'::text, 119::integer, 1::integer, 455::integer),
    ('senate'::text, 119::integer, 2::integer, 80::integer),
    ('senate'::text, 119::integer, 2::integer, 81::integer),
    ('house'::text, 119::integer, 2::integer, 243::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)
            AND v.politician_id NOT IN (
              'aoc', 'barrasso', 'bennie_thompson', 'boebert', 'booker', 'bruce_westerman', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'graham', 'grassley', 'hawley', 'jason_smith', 'jayapal', 'jim_jordan', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'julie_fedorchak', 'kclark', 'kennedy', 'khanna', 'lee', 'mariannette_miller_meeks', 'massie', 'maxine_waters', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_simpson', 'mtg', 'murkowski', 'owens', 'rand_paul', 'rick_crawford', 'rob_bresnahan', 'rubio', 'ryan_mackenzie', 'scalise', 'schiff', 'scott_perry', 'stephanie_bice', 'steve_womack', 'tlaib', 'tom_cole', 'trent_kelly', 'troy_downing', 'warren', 'zeldin'
            ))
    INTO n_rolls, n_votes, n_orphan;

  SELECT count(*) INTO n_issues FROM vr_measure_issues WHERE issue_key = 'israel_support';

  RAISE NOTICE 'Support for Israel: % roll calls, % member votes, % israel_support mappings', n_rolls, n_votes, n_issues;

  IF n_rolls <> 16 THEN
    RAISE EXCEPTION 'Support for Israel: expected 16 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 415 THEN
    RAISE EXCEPTION 'Support for Israel: expected at least 415 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Support for Israel: % member vote(s) on these roll calls carry a politician_id outside the ingest roster', n_orphan;
  END IF;
  IF n_issues < 16 THEN
    RAISE EXCEPTION 'Support for Israel: expected at least 16 israel_support mappings, found %', n_issues;
  END IF;
END $$;
